/* @lc app=leetcode id=1960 lang=kotlin */
class Solution { fun maxProduct(s: String): Long = IntArray(s.length).let { p -> s.indices.fold(0 to 0) { (c, r), i -> ((if (r > i) minOf(r - i, p[2 * c - i]) else 0).let { initialP -> (initialP..s.length).first { d -> i - 1 - d < 0 || i + 1 + d >= s.length || s[i - 1 - d] != s[i + 1 + d] }.also { p[i] = it } }).let { pi -> if (i + pi > r) i to (i + pi) else c to r } }.let { IntArray(s.length).also { left -> s.indices.fold(0 to 1) { (center, maxLen), i -> (center..i).first { ctr -> ctr + p[ctr] >= i }.let { newCenter -> maxOf(maxLen, 2 * (i - newCenter) + 1).also { left[i] = it }.let { newCenter to it } } } } }.let { left -> IntArray(s.length).also { right -> (s.length - 1 downTo 0).fold((s.length - 1) to 1) { (center, maxLen), i -> (center downTo i).first { ctr -> ctr - p[ctr] <= i }.let { newCenter -> maxOf(maxLen, 2 * (newCenter - i) + 1).also { right[i] = it }.let { newCenter to it } } } }.let { right -> (0 until s.length - 1).maxOf { i -> left[i].toLong() * right[i + 1] } } } } }